    {
      "citations": [
        {
          "event_id": "lite_evt_00104",
          "explanation": "The doctor integrated very high glucose with nausea, abdominal symptoms, weakness, confusion, and thirst and escalated immediately.",
          "quote": "恶心、想吐、肚子不舒服、人发软发飘、脑子懵、口很干"
        },
        {
          "event_id": "lite_evt_00393",
          "explanation": "The doctor later provided explicit high- and low-glucose escalation thresholds.",
          "quote": "白天持续超过16-17"
        }
      ],
      "explanation": "Current glucose patterns, hyperglycemia/ketosis symptoms, and hypoglycemia symptoms were repeatedly assessed, with emergency escalation when the symptom pattern changed.",
